                ["EASTUS2"] = new JObject { ["url"] = "{{foundry-eastus2-endpoint}}", ["path"] = "openai", ["deployment"] = "sora-2-slurmfactory-eastus2-glbl", ["priority"] = 2, ["acceptablePriorities"] = "1, 2, 3", ["timeout"] = 240, ["bufferResponse"] = false, ["auth"] = "MI" }
            },

            ["o3-deep-research-slurmfactory-westus-glbl"] = new JObject {
                ["WESTUS"] = new JObject { ["url"] = "{{foundry-westus-endpoint}}", ["path"] = "openai", ["deployment"] = "o3-deep-research-slurmfactory-westus-glbl", ["priority"] = 1, ["acceptablePriorities"] = "1, 2, 3", ["timeout"] = 120, ["bufferResponse"] = false, ["auth"] = "MI" }
            }
        };
    }

@{
        return new JObject {
            ["1"] = new JObject { ["retryCount"] = 2, ["requeue"] = true },
            ["2"] = new JObject { ["retryCount"] = 2, ["requeue"] = true },
            ["3"] = new JObject { ["retryCount"] = 2, ["requeue"] = true }
        };
    }

@{
        string defaultModel = (string)context.Variables["DefaultModel"];
        string modelHeaderName = (string)context.Variables["modelHeaderName"];
        string requested = context.Request.Headers.GetValueOrDefault(modelHeaderName, defaultModel);
        requested = requested?.Trim().ToLowerInvariant();
        return string.IsNullOrWhiteSpace(requested) ? defaultModel?.Trim().ToLowerInvariant() : requested;
    }

@{
        JObject catalog = (JObject)context.Variables["backendCatalog"];
        string model = (string)context.Variables["model"];
        JObject backends = !string.IsNullOrEmpty(model) ? catalog[model] as JObject : null;
        if (backends == null || backends.Count == 0) {
            backends = catalog["DEFAULT"] as JObject ?? new JObject();
        }
        return backends;
    }

@{
        JObject map = (JObject)context.Variables["authResourceByModel"];
        string model = (string)context.Variables["model"];
        return map["DEFAULT"].ToString();
    }

@{
        JObject selected = (JObject)context.Variables["selectedBackends"];
        JArray backends = new JArray();
        string salt = "0123456789"; // 10-digit salt
        using (var sha = System.Security.Cryptography.SHA256.Create()) {
        foreach (var prop in selected.Properties()) {
            JObject src = (JObject)prop.Value;
            JObject backend = new JObject();

            // The property name is the backend label shown in the logs.
            backend["label"] = prop.Name;

            // Required fields.
            backend["url"] = src.Value<string>("url") ?? "";
            backend["priorityGroup"] = src["priority"]?.Value<int>() ?? src["priorityGroup"]?.Value<int>() ?? 1;
            backend["timeout"] = (src["timeout"] != null && src["timeout"].Type != JTokenType.Null) ? src.Value<int>("timeout") : 10;

            // Optional fields with defaults.
            backend["path"] = (src["path"] != null && src["path"].Type != JTokenType.Null) ? src.Value<string>("path") : "openai";
            backend["auth"] = (src["auth"] != null && src["auth"].Type != JTokenType.Null) ? src.Value<string>("auth") : "MI";
            backend["deployment"] = src.Value<string>("deployment") ?? "";
            // acceptablePriorities may be a JArray ([1,2,3]) or a comma-separated string ("1,2,3").
            JToken ap = src["acceptablePriorities"];
            JArray priorities;
            if (ap != null && ap.Type == JTokenType.Array) {
                priorities = (JArray)ap.DeepClone();
            } else if (ap != null && ap.Type == JTokenType.String) {
                priorities = new JArray();
                foreach (string part in ap.Value<string>().Split(new[] { ',', ' ' }, StringSplitOptions.RemoveEmptyEntries)) {
                    if (int.TryParse(part.Trim(), out int p)) { priorities.Add(p); }
                }
            } else {
                priorities = new JArray();
            }
            if (priorities.Count == 0) { priorities = new JArray(1, 2, 3); }
            backend["acceptablePriorities"] = priorities;
            backend["limitConcurrency"] = string.IsNullOrWhiteSpace(src.Value<string>("limitConcurrency")) ? "off" : src.Value<string>("limitConcurrency");
            backend["bufferResponse"] = (src["bufferResponse"] != null && src["bufferResponse"].Type != JTokenType.Null) ? src["bufferResponse"].DeepClone() : true;

            // Join url + path.
            string rawUrl = (backend.Value<string>("url") ?? "").TrimEnd('/');
            string rawPath = (backend.Value<string>("path") ?? "").TrimStart('/');
            string joinedUrl = string.IsNullOrEmpty(rawPath) ? rawUrl : (rawUrl + "/" + rawPath);
            backend["url"] = joinedUrl;

            // Unique per-backend id: hash of url + label.
            string saltedUrl = salt + joinedUrl + prop.Name;
            backend["affinity"] = string.Concat(
                sha.ComputeHash(System.Text.Encoding.UTF8.GetBytes(saltedUrl))
                .Take(10)
                .Select(x => x.ToString("x2"))
            );
            backend["isThrottling"] = false;
            backend["retryAfter"] = DateTime.MinValue;
            backend["defaultRetryAfter"] = 10;

            backends.Add(backend);
        }
        }
        return backends;
    }
